/// <summary>
/// <c>METCommonPrintDestinationService</c> service class use to print the report
/// </summary>
class METCommonPrintDestinationService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// service class process method
/// </summary>
/// <param name = "_contract">METCommonPrintDestinationContract</param>
/// <param name = "sRSPrintDestinationSettings">SRSPrintDestinationSettings</param>
public void process(METCommonPrintDestinationContract _contract, SRSPrintDestinationSettings sRSPrintDestinationSettings)
{
    if (this.isExecutingInBatch())
    {
        METCommonPrintDestinationService::loopRecords(_contract, sRSPrintDestinationSettings);
    }
}

/// <summary>
/// loop record method
/// </summary>
/// <param name = "_contract">METCommonPrintDestinationContract</param>
/// <param name = "_srsPrintDestinationSettings">SRSPrintDestinationSettings</param>
public static void loopRecords(METCommonPrintDestinationContract _contract, SRSPrintDestinationSettings _srsPrintDestinationSettings)
{
    System.     Exception       ex;
    container   conRecord = _contract.parmRecordCon();

    for(int conCounter = 1; conlen(conRecord) >= conCounter; conCounter++)
    {
        try
        {
            //// generate code
            if(_contract.parmDocType() == PrintMgmtDocumentType::SalesOrderInvoice)
            {
                METCommonPrintDestinationService::generateSOShipment(_contract, _srsPrintDestinationSettings, conPeek(conRecord, conCounter));
            }
            else
            {
                _contract.parmRecordId(conPeek(conRecord, conCounter));
                METCommonPrintDestinationService::generateReport(_contract, _srsPrintDestinationSettings);// it may differ based on the requirement of the report
            }
        }
        catch
        {
            ex = CLRInterop::getLastException().GetBaseException();

            continue;
        }
    }
}

/// <summary>
/// generateSOShipment method
/// </summary>
/// <param name = "_contract">METSOPrintDestinationContract</param>
/// <param name = "_srsPrintDestinationSettings">SRSPrintDestinationSettings</param>
/// <param name = "_recId">RefRecId</param>
public static void generateSOShipment(METCommonPrintDestinationContract _contract, SRSPrintDestinationSettings _srsPrintDestinationSettings, RefRecId _recId)
{
    SalesPackingSlipJournalPrint        salesPackingSlipJournalPrint;
    SalesInvoiceJournalPrint            salesInvoiceJournalPrint;
    boolean                             packingslipHasRecord = false;
    boolean                             invoiceHasRecord = false;
    METSalesOrderShipmentLoadHeader     metSOShipmentLoadHeader;

    Set packingslipSet  = new Set(Types::Record);
    Set invoiceSet      = new Set(Types::Record);

    select firstonly metSOShipmentLoadHeader
        where metSOShipmentLoadHeader.RecId == _recId;

    If(metSOShipmentLoadHeader.DocumentStatus == DocumentStatus::PackingSlip)
    {
        CustPackingSlipJour                 packingSlipJour;

        while select packingSlipJour
                where packingSlipJour.METShipmentId == metSOShipmentLoadHeader.ShipmentId
        {
            // Add record
            packingslipSet.add(packingSlipJour);
            packingslipHasRecord = true;
        }
    }
    else if (metSOShipmentLoadHeader.DocumentStatus == DocumentStatus::Invoice)
    {
        CustInvoiceJour                 invoiceJour;

        while select invoiceJour
                where invoiceJour.METShipmentId == metSOShipmentLoadHeader.ShipmentId
        {
            // Add record
            invoiceSet.add(invoiceJour);
            invoiceHasRecord = true;
        }
    }

    if(packingslipHasRecord)
    {
        container               printSetting;
        // Set printer settings
        salesPackingSlipJournalPrint = SalesPackingSlipJournalPrint::construct();
        salesPackingSlipJournalPrint.parmPrintFormletter(NoYes::Yes);
        salesPackingSlipJournalPrint.parmUsePrintManagement(_contract.parmUsePrintMgmt());

        printSetting = salesPackingSlipJournalPrint.parmPrinterSettingsFormLetter();
        salesPackingSlipJournalPrint.parmPrinterSettingsFormLetter(_contract.parmUsePrintMgmt() == NoYes::Yes ? printSetting : _srsPrintDestinationSettings.pack());

        // Print
        salesPackingSlipJournalPrint.printJournal(packingslipSet);
    }

    if(invoiceHasRecord)
    {
        container               printSetting;
        // Set printer settings
        salesInvoiceJournalPrint = SalesInvoiceJournalPrint::construct();
        salesInvoiceJournalPrint.parmPrintFormletter(NoYes::Yes);
        salesInvoiceJournalPrint.parmUsePrintManagement(_contract.parmUsePrintMgmt());

        printSetting = salesInvoiceJournalPrint.parmPrinterSettingsFormLetter();
        salesInvoiceJournalPrint.parmPrinterSettingsFormLetter(_contract.parmUsePrintMgmt() == NoYes::Yes ? printSetting : _srsPrintDestinationSettings.pack());

        // Print
        salesInvoiceJournalPrint.printJournal(invoiceSet);
    }
}

/// <summary>
/// generateReport method
/// </summary>
/// <param name = "_contract">METCommonPrintDestinationContract</param>
/// <param name = "_sRSPrintDestinationSettings">SRSPrintDestinationSettings</param>
public static void generateReport(METCommonPrintDestinationContract _contract, SRSPrintDestinationSettings _sRSPrintDestinationSettings)
{
    SRSPrintDestinationSettings                     settings;
    SrsReportRunController                          controller  = new SrsReportRunController();
    METCommonReportContract                         contract    = new METCommonReportContract();

    contract.parmRecId(_contract.parmRecordId());

    controller.parmArgs(new Args());
    controller.parmReportName(METCommonPrintDestinationService::getReportName(_contract.parmDocType()));
    controller.parmDialogCaption(METCommonPrintDestinationService::getCaption(_contract.parmDocType()));
    controller.parmShowDialog(false);
    //controller.parmLoadFromSysLastValue(false);
    controller.parmReportContract().parmRdpContract(contract);

    if(!_contract.parmUsePrintMgmt())
    {
        if(_sRSPrintDestinationSettings == null)
        {
            settings = controller.parmReportContract().parmPrintSettings();
            SRSPrintMedium printMedium  = settings.printMedium();
            printMedium = new SRSPrintMediumScreen();
            settings.printMedium(printMedium);
            controller.parmReportContract().parmPrintSettings(settings);
        }
        else
        {
            controller.parmReportContract().parmPrintSettings(_sRSPrintDestinationSettings);
        }
    }

    controller.startOperation();
}

/// <summary>
/// method to fetch the report name
/// </summary>
/// <param name = "_docType">PrintMgmtDocumentType</param>
/// <returns>str</returns>
public static str getReportName(PrintMgmtDocumentType _docType)
{
    ReportName  reportName;
    switch(_docType)
    {
        case PrintMgmtDocumentType::METContainerContentReport : // name of the menuitem
            reportName = ssrsReportStr(METCCRReport, Report); // Report name should be assigned based on the menuitem
            break;
        case PrintMgmtDocumentType::METTOMultimodalDangerousGoods : 
            reportName = ssrsReportStr(METMultimodalDangerousGoods, Report); 
            break;
        case PrintMgmtDocumentType::METSOMultimodalDangerousGoods :
            reportName = ssrsReportStr(METSalesMultimodalDangerousGoods, Report);
            break;

        default:
            reportName = ''; // Report name should be assigned based on the menuitem
            break;
    }

    return reportName;
}

/// <summary>
/// method to get dialog caption
/// </summary>
/// <param name = "_docType">PrintMgmtDocumentType</param>
/// <returns>str</returns>
public static str getCaption(PrintMgmtDocumentType _docType)
{
    str  label;
    switch(_docType)
    {
        case PrintMgmtDocumentType::METContainerContentReport : // name of the menuitem
            label = "@MET:SODConContentReport"; //Report name should be assigned based on the menuitem
            break;

        case PrintMgmtDocumentType::METTOMultimodalDangerousGoods :
            label = "@MET:SODMultimodalDG";
            break;

        case PrintMgmtDocumentType::METSOMultimodalDangerousGoods :
            label = "@MET:SODMultimodalDG";
            break;

        default:
            label = ''; //Report name should be assigned based on the menuitem
            break;
    }

    return label;
}
